from lib import *
S = SS('h2')
steps = [
    step("消息大小不同时,DATA 帧怎么切(抓包代理看客户端发出的帧)。payload 0 字节的请求:protobuf 3 字节,一个 8 字节的 DATA 帧;payload 300 字节:消息总长 311,一个 DATA 帧;16000 字节:一个 16011 字节的 DATA 帧;20000 字节:消息总长 20012,切成 16384 和 3628 两个 DATA 帧;70000 字节:切成 6 个 DATA 帧(16384、16384、16384、12755、3628、4477);1 MiB 的 payload:共 65 个 DATA 帧。每种大小前缀里的长度字段都等于 protobuf 的长度(300 字节的 payload 是 306),把所有 DATA 帧负载拼起来再按前缀切,恰好得到一条消息、没有剩余字节。一条 gRPC 消息的边界由 5 字节前缀决定,和 HTTP/2 的帧边界无关。", t=tl(S(1)), done=lidx(S(1), '20000  '), mark=lidx(S(1), '1048576'), b=bars([['payload 300 → DATA 帧数', 1, '1'], ['payload 20000 → DATA 帧数', 2, '2'], ['payload 70000 → DATA 帧数', 6, '6'], ['payload 1 MiB → DATA 帧数', 65, '65']], 70, done=[1, 2], mark=[3]), kv=KV([['HTTP/2 单帧', '最多 16384 字节(默认)'], ['20000 字节的 payload', '切成 16384 + 3628 两个 DATA 帧'], ['消息边界', '看 5 字节前缀,不看帧边界']], ['消息边界'])),
    step("一条流里的多条消息:服务端流返回 3 条消息,每条自己带 5 字节前缀。服务端发了 3 个 DATA 帧,负载长度 9、11、11;按前缀切出 3 条消息,protobuf 长度分别是 4、6、6,标志都是 0,没有剩余字节。这里每条消息各占一个 DATA 帧,但这是 grpc-go 的写法,不是协议要求——协议允许一个 DATA 帧装多条消息,也允许一条消息跨多个 DATA 帧(上一步)。", t=tl(S(2)), done=lidx(S(2), '服务端 DATA 帧 3 个'), b=bars([['消息 1 的 DATA 负载', 9, '9'], ['消息 2', 11, '11'], ['消息 3', 11, '11']], 12, done=[0, 1, 2]), kv=KV([['3 条消息', '3 个 DATA 帧,负载 9、11、11'], ['protobuf 长度', '4、6、6'], ['协议', '一帧多消息或一消息多帧都允许']], ['3 条消息'])),
    step("开启 gzip 压缩(grpc.UseCompressor(gzip.Name)):请求头多出 grpc-encoding: gzip 和 grpc-accept-encoding: gzip;原始 payload 5500 字节(重复的 hello gRPC),线上这一条消息的压缩标志变成 1,长度字段是 73——压缩后的 gzip 字节数,不是原始长度;服务端的响应头里也带 grpc-encoding: gzip。压缩是对每一条消息单独做的,标志位告诉对方这一条是不是压缩过的,所以同一条流里的消息可以有的压缩、有的不压缩。", t=tl(S(3)), done=lidx(S(3), '原始 payload 5500'), mark=lidx(S(3), '请求头 grpc-encoding'), b=bars([['原始 payload 字节', 5500, '5500'], ['线上这条消息长度字段', 73, '73']], 5600, mark=[0], done=[1]), kv=KV([['请求头', 'grpc-encoding: gzip,grpc-accept-encoding: gzip'], ['压缩标志', '1,长度字段 = 压缩后 73 字节'], ['粒度', '每条消息单独压缩']], ['压缩标志'])),
    step("空消息 Req{} 的编码:DATA 帧负载只有 5 个字节 0000000000——压缩标志 0、长度 0,没有载荷,同时带 END_STREAM。proto3 的默认值不写出,所以全是默认值的消息编码后是 0 字节的 protobuf,但 gRPC 仍然要发 5 字节前缀(见编码系列的 protobuf 一篇)。", t=tl(S(4)), done=lidx(S(4), 'DATA 帧负载 5 字节'), b=bars([['空消息 protobuf', 0, '0'], ['空消息 DATA 负载', 5, '5']], 6, done=[1]), kv=KV([['DATA 帧负载', '5 字节 0000000000'], ['含义', '标志 0,长度 0,无载荷'], ['END_STREAM', '同一个帧带上']], ['DATA 帧负载'])),
    step("客户端发超过服务端接收上限(默认 4 MiB)的消息:5 MiB 的请求,客户端得到 code=ResourceExhausted,message 是 “grpc: received message larger than max (5242890 vs. 4194304)”,用时 2.5 ms。线上客户端到服务端实际只传了 786960 字节(消息本身 5242880 字节),服务端到客户端 172 字节。服务端读到前缀里的长度就知道超限,立刻回一个 HEADERS(:status: 200; grpc-status: 8; grpc-message: …,没有 DATA,这就是 trailers-only 响应)并发 RST_STREAM(错误码 NO_ERROR)结束这条流。客户端停止发送之前已经发出去的字节数每次运行不一样(第一次是 262326)。", t=tl(S(5)), done=lidx(S(5), '客户端得到 code=ResourceExhausted'), mark=lidx(S(5), '线上客户端→服务端'), b=bars([['消息本身 字节(千)', 5243, '5243'], ['线上实际传输(千)', 787, '787'], ['服务端→客户端 字节', 172, '172']], 5300, done=[1], mark=[0]), kv=KV([['code', 'ResourceExhausted(grpc-status 8)'], ['响应', '一个 HEADERS 同时带 :status 与 grpc-status,没有 DATA'], ['传输量', '786960 字节,远少于 5 MiB']], ['code'])),
]
A = mkarth('h2', 2, 'gRPC,消息帧,5 字节前缀,DATA,压缩,最大消息,Go,真实验证,动画演示',
    '抓包看 gRPC 的消息帧:消息边界由 5 字节前缀决定,和 HTTP/2 DATA 帧边界无关(20000 字节切成 16384 + 3628,1 MiB 切成 65 帧);gzip 压缩是逐条消息的,标志位为 1、长度是压缩后的;超过 4 MiB 的消息服务端读到长度就拒绝,线上只传了一小部分。',
    '上一篇看到一条消息是 5 字节前缀加 protobuf。这篇继续追问:消息大了会怎样,多条消息怎么排,压缩标志怎么用,超过大小限制时线上发生了什么?',
    [('73 对 5500', '开启 gzip 后,线上一条消息的长度字段(压缩后)与原始 payload 字节'), ('65 个', '1 MiB 的消息在 HTTP/2 上被切成的 DATA 帧个数(默认单帧上限 16384 字节)'), ('786960 字节', '5 MiB 的请求被服务端以 ResourceExhausted 拒绝时,线上客户端实际发出的字节数')],
    [('前缀与帧', '<p>一条 gRPC 消息 = 1 字节压缩标志 + 4 字节大端长度 + 载荷。HTTP/2 单个 DATA 帧最多 16384 字节(默认),大消息被切成多个 DATA 帧,接收方把负载拼起来再按前缀切。消息边界与帧边界无关。</p>'),
     ('多条消息', '<p>一条流里可以有任意多条消息(流式 RPC)。grpc-go 每条消息一个 DATA 帧,但协议不要求。</p>'),
     ('压缩', '<p>压缩标志位是 1 时,载荷是压缩后的字节,长度字段是压缩后的长度,编码方式写在请求头 grpc-encoding 里。压缩是逐条消息的,所以也可以同一条流里有的压缩有的不压缩。</p>'),
     ('空消息', '<p>空消息仍然要 5 字节前缀:标志 0、长度 0。</p>'),
     ('大小限制', '<p>服务端默认只接收 4 MiB 以内的消息。读到前缀里的长度大于限制就立刻回 ResourceExhausted 并结束流,不会把 5 MiB 全收完;客户端是否已发出大部分字节,取决于时机。</p>')],
    steps,
    [ENV_H + '。抓包代理见第 1 篇;第一节每种大小在新的流上各调用一次(流编号 3、5、7……);DATA 帧的切法受流控窗口和写入时机影响,同一个大小多次运行,帧长度可能不同(70000 字节那一行是一次运行的结果);第五节线上传输的字节数每次运行不同',
     '没有验证:协议规范里对 DATA 帧和消息关系的原文规定(只观察了 grpc-go 的行为);设置 SETTINGS_MAX_FRAME_SIZE 更大时的切法;其它压缩算法(snappy 等第三方注册的);客户端发送大小限制(MaxCallSendMsgSize)的行为;服务端流里每条消息的大小限制对整条流是否累计'],
    '消息帧')
